SourceCode.Declaration:
/// <summary>
/// reportDiscrepancy's answer. TriggeredJournalId is set when the server created a triggered count.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountDiscrepancyResponse
{
    boolean success;
    str     errorCode;
    str     message;
    str     triggeredJournalId;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('TriggeredJournalId')]
public str parmTriggeredJournalId(str _value = triggeredJournalId)
{
    triggeredJournalId = _value;
    return triggeredJournalId;
}
